import{z as o,x as B,o as r,c as d,q as A,j as i,D as e,d as n,s as l,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"融券与转融通","description":"","frontmatter":{"title":"融券与转融通","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-securities-lending.md","filePath":"quant/cn-securities-lending.md","lastUpdated":1791063341000}'),p={name:"quant/cn-securities-lending.md"};function u(D,a,h,c,m,C){const t=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=A('<h1 id="融券与转融通" tabindex="-1">融券与转融通 <a class="header-anchor" href="#融券与转融通" aria-label="Permalink to &quot;融券与转融通&quot;">​</a></h1><div class="epigraph"><p>转融通曾是券源从持有人经中国证券金融公司转到券商再融给客户的公开管道。管道收紧或暂停后，空头可行集不是策略参数，是公告日切换的状态。</p><footer>—— 《转融通业务监督管理试行办法》；中国证监会 2024 年 7 月 10 日关于暂停转融券的公开说明；交易所《融资融券交易实施细则》</footer></div><p><a href="/quant/cn-private-neutral">上一课</a>需要空头腿。<a href="/quant/cn-short-constraint">做空约束</a>已写标的、提价、保证金与禁止裸卖空。本课的缺口是<strong>券源供给的制度管道</strong>：转融通、转融券、战略配售出借与 2024 年暂停。不重复前端检查细节，只补供给如何进入<a href="/quant/securities-lending">借券成本</a>的 A 股版本。后课对冲成本把期货基差与融券费放在同一张账单上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无转融通时，券商融券主要靠自有与客户约定出借，供给窄、易召回。转融通把保险、公募、战略配售等持有人的券集中再分配，扩大了可融名单与数量，也使供给对政策更敏感。证监会 2024 年 7 月批准中证金融暂停转融券，存量限期了结，并上调融券保证金。问题是回测必须按公告切换：暂停后假设「转融券库存仍可开新空」的路径结束。把 2019–2023 的可融宇宙沿用到 2024 年下半年，是在交易一个当时关闭的市场。<span class="marginnote">数字实例：公开的融券余量是全市场已借出、尚未归还的存量。某券余量 5000 万股看似池子不小，但这 5000 万股全押在别人的空单里没还；你能借到多少取决于券商柜台剩下的券，可能是零。拿余量当可借量代理，会系统性高估可开仓规模——余量是「已占用」，不是「可占用」。</span></p><p>战略配售股份出借曾被限制：新上市股份进入融券的时间与比例是监管对象。量化若在上市初期做空「定价偏高」的新股，须检查当时是否允许该券进入出借。这与注册制新股课衔接，本课只钉券源。</p><h3 id="费率与余量是滞后观察" tabindex="-1">费率与余量是滞后观察 <a class="header-anchor" href="#费率与余量是滞后观察" aria-label="Permalink to &quot;费率与余量是滞后观察&quot;">​</a></h3><p>市场公开的融券余量、两融余额是存量，不是你的可借报价。点-in-time 的可融数量在券商柜台，研究常用余量当代理，会高估可开仓规模——余量已被他人占用。成本用费率分布的右尾，不用均值：特殊券与政策日的费率可以吃掉空头溢价。</p><p><span class="marginnote">融券卖出所得一般不能随意取用，担保与平仓规则见<a href="/quant/cn-margin-trading">两融保证金</a>。把融券当现金杠杆会错科目。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>状态变量：<code>transfer_lending ∈ {on, restricted, paused}</code> 按公告日。宇宙：交易所融券标的 ∩ 当时可获得券源代理。开仓：提价规则 + 保证金类别（私募更高）。持有：召回与标的调出强制了结。报告：无约束多空 vs 管道约束后多空。容量按可借库存与集中度，不按 ADV。<span class="marginnote">「转融通」就是给券源修的一条批发渠道：保险、公募这类长期持有人把券「转」给中证金融，中证金融再批给券商，券商零售给融券客户。券商自己囤的券很少，渠道一关，绝大多数股票立刻无券可融——这就是为什么它是一个状态变量而不是一个费率参数。</span></p>',11)),(r(),i(s,null,{default:e(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E5%9B%9E%E6%B5%8B%E6%97%A5%E8%90%BD%E5%9C%A8%E6%9F%90%E5%85%AC%E5%91%8A%E6%97%A5%E4%B9%8B%E5%90%8E%22%5D%20--%3E%20S%7B%22transfer_lending%20%E7%8A%B6%E6%80%81%22%7D%0A%20%20S%20--%3E%7C%22on%22%7C%20A%5B%22%E8%BD%AC%E8%9E%8D%E5%88%B8%E5%8F%AF%E5%BC%80%E6%96%B0%E7%A9%BA%20%E8%AE%B0%E8%9E%8D%E5%88%B8%E8%B4%B9%E7%8E%87%22%5D%0A%20%20S%20--%3E%7C%22restricted%22%7C%20B%5B%22%E5%90%8D%E5%8D%95%E4%B8%8E%E6%AF%94%E4%BE%8B%E7%BC%A9%E7%AA%84%20%E5%8F%AA%E5%87%86%E5%AD%98%E9%87%8F%22%5D%0A%20%20S%20--%3E%7C%22paused%22%7C%20C%5B%22%E7%A6%81%E6%AD%A2%E6%96%B0%E5%BC%80%E8%9E%8D%E5%88%B8%E7%A9%BA%E5%8D%95%22%5D%0A%20%20C%20--%3E%20ALT%5B%22%E7%A9%BA%E5%A4%B4%E9%9C%80%E6%B1%82%E8%BD%AC%E5%90%91%E8%82%A1%E6%8C%87%E6%9C%9F%E8%B4%A7%E5%AF%B9%E5%86%B2%22%5D%0A%20%20A%20--%3E%20CAP%5B%22%E5%AE%B9%E9%87%8F%E6%8C%89%E5%8F%AF%E5%80%9F%E5%BA%93%E5%AD%98%E4%B8%8E%E9%9B%86%E4%B8%AD%E5%BA%A6%E8%AE%A1%22%5D%0A%20%20B%20--%3E%20CAP%0A%20%20ALT%20--%3E%20CAP%0A%20%20CAP%20--%3E%20RPT%5B%22%E5%88%86%E5%88%97%E6%8A%A5%E5%91%8A%20%E6%97%A0%E7%BA%A6%E6%9D%9F%20vs%20%E7%AE%A1%E9%81%93%E7%BA%A6%E6%9D%9F%E5%90%8E%E5%A4%9A%E7%A9%BA%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<p>与期货对冲的替代弹性：转融券暂停后，中性需求更挤入期货，贴水机制见下课。不要在暂停期用历史融券费去填空头腿。</p><h3 id="出借人激励" tabindex="-1">出借人激励 <a class="header-anchor" href="#出借人激励" aria-label="Permalink to &quot;出借人激励&quot;">​</a></h3><p>公募与指数基金出借可增增强收益，但受产品规则与监管窗口影响。供给是内生政策变量，不是稳定的结构性 alpha 来源。把「出借收益」写进指增预期时，须声明政策情景。<span class="marginnote">常见误区：初学者容易把融券费率当成像管理费一样的固定数字。实际上它是右偏分布：多数时候 1–2% 的普通券，在政策公告日、special 回购时点或紧券上可以跳到两位数，甚至直接无券可借。空头腿成本要用分布右尾做压力测试，拿均值进净值模型会在最需要空头的那几天严重低估成本。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>搜寻与匹配在 A 股被高度中介化：中证金融与券商是节点。政策改变节点流量，费率与余量同跳。价格发现：可空集合变窄，负面信息写入更慢，与 Miller / Hong–Scheinkman–Xiong 方向一致，但识别必须用制度断点，不能只用余量截面当因果。</p><p>交收：融券仍要交得起券；T+1 与前端检查把大量 fail 挡在撮合前。剩余的运营失败仍应按<a href="/quant/settlement-fails">结算失败</a>记账。</p>',6)),(r(),i(s,null,{default:e(()=>[l(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Holder%5B%22%E5%87%BA%E5%80%9F%E4%BA%BA%20%E5%85%AC%E5%8B%9F%20%E4%BF%9D%E9%99%A9%20%E6%88%98%E7%95%A5%E9%85%8D%E5%94%AE%22%5D%20--%3E%20CSF%5B%22%E4%B8%AD%E8%AF%81%E9%87%91%E8%9E%8D%E8%BD%AC%E8%9E%8D%E9%80%9A%22%5D%0A%20%20CSF%20--%3E%20Broker%5B%22%E5%88%B8%E5%95%86%E8%9E%8D%E5%88%B8%22%5D%0A%20%20Broker%20--%3E%20Short%5B%22%E5%AE%A2%E6%88%B7%E8%9E%8D%E5%88%B8%E5%8D%96%E5%87%BA%22%5D%0A%20%20Pol%5B%22%E6%94%BF%E7%AD%96%20%E6%9A%82%E5%81%9C%E6%88%96%E9%99%90%E5%88%B6%22%5D%20--%3E%20CSF%0A%20%20Pol%20--%3E%20Broker%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E("h2",{id:"边界",tabindex:"-1"},[n("边界 "),E("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[5]||(a[5]=E("p",null,"不提供寻找灰色券源、规避暂停或借用他人账户融券的方法。现行以证监会公告与细则为准。港股做空与 A 股融券不可混用一套费率。",-1)),a[6]||(a[6]=E("h2",{id:"小结",tabindex:"-1"},[n("小结 "),E("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[7]||(a[7]=E("ul",null,[E("li",null,"转融通是券源管道；2024 年暂停是状态切换，须按公告回测。"),E("li",null,"余量不是你的可借量；费率用右尾。"),E("li",null,"管道关闭把中性需求推向期货基差。"),E("li",null,"出处：转融通试行办法；证监会 2024-07-10 公开说明；交易所两融细则。")],-1))])}const g=o(p,[["render",u]]);export{_ as __pageData,g as default};
